<form method="post" action="<?=e(url('/admin/settings'))?>" class="admin-card form-card resource-form"><?=csrf_field()?><?php $group='';foreach($items as $item):if($group!==$item['setting_group']):$group=$item['setting_group'];?><h2 class="wide"><?=e(ucwords($group))?></h2><?php endif;?><label><?=e(ucwords(str_replace('_',' ',$item['setting_key'])))?><?php if($item['type']==='textarea'):?><textarea name="settings[<?=e($item['setting_key'])?>]" rows="3"><?=e($item['setting_value'])?></textarea><?php else:?><input type="<?=e($item['type']==='email'?'email':($item['type']==='url'?'url':'text'))?>" name="settings[<?=e($item['setting_key'])?>]" value="<?=e($item['setting_value'])?>"><?php endif;?></label><?php endforeach;?><div class="form-actions wide"><button class="primary-button">Save settings</button></div></form>
